// CSD_RATIONALE_BEGIN
// Root-cause of previous best (34.7%, 79.6% syntax):
//   mode_A (15 examples): GenerateWithPrefixAndManagedSpan enters constrained mode
//     whenever the LM naturally writes "<<" during reasoning. Single variable names
//     like <<n1>> are complete parses, so the tiny span is immediately closed and
//     extracted as the final answer.
//   mode_C/G (9 examples): Model reasons to EOS before budget-forced span opening,
//     or prefixBudget timing misses the model's natural EOS.
//   Unterminated (9 examples): Model writes << near end of budget with too few
//     remaining steps for the constrained expression.
//
// New strategy: Hand-write a Phase 1 free loop that NEVER triggers constrained mode,
// even if the LM writes "<<" in reasoning. At prefixBudget (70% = 630/900 steps),
// force ONE OpenConstrainedSpan, then close it with CloseSpanWithinBudget (~269 steps).
//
// Effects:
//   - Tiny spans (mode_A): remain as free text; evaluator extracts LAST span = ours ✓
//   - Unterminated (9): CloseSpanWithinBudget has 269 steps; avg span is 5.25 tokens ✓
//   - No-span (mode_C/G): forced OpenConstrainedSpan guarantees at least one span ✓
//   - Accuracy: model reasons freely for 630 steps then LM context drives expression ✓
//
// prefixBudget = 70% of maxSteps = 630 for maxSteps=900
// closeBudget  ≈ 269 steps (maxSteps - prefixBudget - 1)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//    Phase 1 loop invariant !insideConstrainedOut makes the implication vacuously true
//    throughout the free loop; no branch inside the loop sets insideConstrainedOut.
//    After OpenConstrainedSpan, currentConstrainedOut == [] which satisfies
//    parser.IsValidPrefix([]) by the method precondition. If entering Phase 2 from
//    the initial insideConstrained=true path, the precondition directly supplies
//    parser.IsValidPrefix(currentConstrained). CloseSpanWithinBudget postcondition
//    guarantees insideOut ==> parser.IsValidPrefix(currentOut) on return, so
//    validity is preserved in every branch.
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//    Phase 1: each iteration calls UnconstrainedStep (+1 to steps) and appends at
//    most one non-EOS token to generated, maintaining the bound at each step.
//    OpenConstrainedSpan appends exactly one "<<" token and costs one step
//    (+1 to both generated length and steps). CloseSpanWithinBudget with
//    closeBudget = maxSteps - steps satisfies |cg| <= |generated| + closeBudget;
//    after it returns we set steps := maxSteps, so
//    |generated| <= |generatedPrefix| + (prefixBudget+1) + closeBudget
//              = |generatedPrefix| + prefixBudget + 1 + (maxSteps - prefixBudget - 1)
//              = |generatedPrefix| + maxSteps. Tokens consumed by EOS or rejected
//    suffix inside CloseSpanWithinBudget count toward the budget but do not grow
//    visible output, so visible growth stays within the consumed step count.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm, "Solve step by step. At the very end, write the final answer ONCE as <<int(expression)>> using only: bare variable names (no braces), integers, +, -, *, /, //, %, (, ), int(). Example: <<int(n * price + base)>>. No LaTeX, no {}, no **. Only ONE <<>> at the very end of your answer.");

  var steps: nat := 0;

  // Prefix budget: 70% of maxSteps, capped to leave at least 2 steps for span open + close
  var prefixBudget: nat := (maxSteps * 70) / 100;
  if maxSteps <= 2 {
    prefixBudget := 0;
  } else if prefixBudget > maxSteps - 2 {
    prefixBudget := maxSteps - 2;
  }

  // Phase 1: Free unconstrained generation, deliberately NOT entering constrained mode
  // even if the LM writes << >> tokens (they remain as plain free text).
  if !insideConstrainedOut {
    while steps < prefixBudget
      invariant 0 <= steps <= prefixBudget
      invariant prefixBudget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant |generated| <= |generatedPrefix| + steps
      decreases prefixBudget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Force exactly one constrained span at the end of the prefix budget
    if steps < maxSteps {
      var go, io, co := helpers.OpenConstrainedSpan(lm, generated);
      generated := go;
      insideConstrainedOut := io;
      currentConstrainedOut := co;
      steps := steps + 1;
    }
  }

  // Phase 2: Close the constrained span within the remaining budget
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  }

  cost := steps;
}

